package com.metabuild.app.config;
import com.metabuild.infrastructure.security.SaTokenSessionControl;import com.metabuild.modules.admin.auth.application.RefreshTokenStore;import com.metabuild.modules.admin.profile.application.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;
final class SaProfileSessionAdapter implements ProfileSessionPort {private final SaTokenSessionControl sessions;private final RefreshTokenStore refresh;SaProfileSessionAdapter(SaTokenSessionControl sessions,RefreshTokenStore refresh){this.sessions=sessions;this.refresh=refresh;}public String currentSessionId(){String value=sessions.currentTokenValue();return value==null?null:id(value);}public List<LoginDeviceView> devices(UUID user){String current=currentSessionId();return sessions.tokenValues(user.toString()).stream().filter(sessions::tokenActive).map(token->{String id=id(token);return new LoginDeviceView(id,"Authenticated session","Unknown","Unknown",null,id.equals(current));}).toList();}public void revoke(UUID user,String sessionId){String token=sessions.tokenValues(user.toString()).stream().filter(sessions::tokenActive).filter(x->id(x).equals(sessionId)).findFirst().orElse(null);if(token!=null)sessions.logoutToken(token);}public void credentialsChanged(UUID user,String protectedSessionId,long targetRevision){refresh.revokeAll(user);sessions.tokenValues(user.toString()).stream().filter(sessions::tokenActive).filter(token->!Objects.equals(id(token),protectedSessionId)).filter(token->{Long revision=sessions.credentialRevision(token);return revision==null||revision<targetRevision;}).forEach(sessions::logoutToken);}private static String id(String token){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8))).substring(0,32);}catch(Exception e){throw new IllegalStateException(e);}}}
